// The fixtures were generated by uv run python (see the `generator` field in
// fixtures.json): the real Day-4 decision tools over the registered champion's
// seed-42 test split, plus the 15 seed-eval questions replayed through the full
// copilot pipeline offline (keyword router + template writer). mock = true.
import raw from "./fixtures.json"
import type { CopilotDemo, Fixtures } from "@/api/types"

export const fixtures = raw as unknown as Fixtures

/** Live-run, Day-5 measured constants (docs/concepts.md §Day 5) used for the
 * captions that describe what the *live* service does; playback is offline. */
export const MEASURED = {
  gate_latency_s: 1.22,
  fast_path_band_s: "1.16–1.25 s (gate-only, 0 writer tokens)",
  context_boot_s: 0.4,
  first_explain_s: "~30 s (one-time 25.1 s policy-tree fit, cached after)",
  p50_s: 4.93,
  p95_s: 9.45,
  seed_fast_path_accuracy: "1.00 (0.93–1.00) with the Decisions API",
  writers: [
    {
      name: "ollama gpt-oss:120b-cloud",
      description: "default writer · ~3.6 s · 268-word brief · passes V1–V4",
    },
    {
      name: "template floor",
      description: "<0.01 s · passes V1–V4 · always-on degraded mode",
    },
    {
      name: "neurometric goal-setter",
      description: "fails V1+V3 live (850 words, derived numbers) — needs a general model",
    },
  ],
  source: "docs/concepts.md §Day 5",
} as const

const normalize = (s: string) =>
  s
    .toLowerCase()
    .replace(/[^a-z0-9\s]+/g, " ")
    .replace(/\s+/g, " ")
    .trim()

const tokens = (s: string) => new Set(normalize(s).split(" "))

/** Jaccard overlap on word tokens; playback matching for typed questions. */
function similarity(a: string, b: string): number {
  const wa = tokens(a)
  const wb = tokens(b)
  let inter = 0
  for (const t of wa) if (wb.has(t)) inter++
  const union = wa.size + wb.size - inter
  return union === 0 ? 0 : inter / union
}

/** Best-effort match of a typed question against the recorded seed corpus. */
export function findDemo(question: string): CopilotDemo | null {
  let best: { score: number; demo: CopilotDemo } | null = null
  for (const demo of fixtures.copilot_demos) {
    const score = similarity(question, demo.question)
    if (!best || score > best.score) best = { score, demo }
  }
  if (!best) return null
  return best.score >= 0.55 || normalize(question) === normalize(best.demo.question)
    ? best.demo
    : null
}
